// examples/composition.mjs
function composition() {
  const baseUrl = process.env.DWK_BASE_URL ?? "http://localhost";
  const dataDir = process.env.DWK_DATA_DIR ?? "./data";
  const env = assembleBindings({ dataDir });
  env.WEBAUTHN = createDurableObjectNamespace(WebAuthnObject, {
    dataDir,
    env,
    className: "webauthn",
  });
  return {
    baseUrl,
    dataDir,
    publicDir: process.env.DWK_PUBLIC_DIR,
    env,
    mounts: [
      {
        name: "@dwk/webfinger",
        handler: createWebfinger({ resolve: () => null }),
        reservedPaths: ["/.well-known/webfinger"],
      },
      {
        name: "@dwk/webauthn",
        handler: createWebAuthn({
          rpId: new URL(baseUrl).hostname,
          rpName: "dwk self-host",
          origin: baseUrl,
        }),
        reservedPaths: ["/register", "/authenticate"],
        requires: ["WEBAUTHN"],
      },
    ],
  };
}

// examples/serve.mjs
var write = (stream) => (event, fields) =>
  stream.write(
    `dwk-serve ${event}${fields ? ` ${JSON.stringify(fields)}` : ""}
`,
  );
var logger = {
  debug: () => {},
  info: write(process.stdout),
  warn: write(process.stderr),
  error: write(process.stderr),
};
startServer(composition(), { logger }).catch((err) => {
  process.stderr.write(`dwk-serve: ${err?.message ?? String(err)}
`);
  process.exit(1);
});
